package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	n := nextInt(scanner)
	m := nextInt(scanner)
	k := nextLong(scanner)

	var ansX, ansY int64

	if k < int64(n) {
		ansX = k + 1
		ansY = 1
	} else {
		k -= int64(n)
		count := k / int64(m-1)
		ansX = int64(n) - count
		rem := k % int64(m-1)
		if count%2 == 0 {
			ansY = 2 + rem
		} else {
			ansY = int64(m) - rem
		}
	}

	fmt.Printf("%d %d\n", ansX, ansY)
}

func nextInt(scanner *bufio.Scanner) int {
	scanner.Scan()
	v, _ := strconv.Atoi(scanner.Text())
	return v
}

func nextLong(scanner *bufio.Scanner) int64 {
	scanner.Scan()
	v, _ := strconv.ParseInt(scanner.Text(), 10, 64)
	return v
}

